   onTileVisible?: (tile: Cesium3DTile) => void;
 };

 export type Cesium3DTilesetOtherProps = EventProps<Cesium3DTileFeature> & {
   /** Calls when the tile set is completely loaded. */
   onReady?: (tileset: CesiumCesium3DTileset) => void;
 };

