   "dynamicScreenSpaceErrorFactor",
   "dynamicScreenSpaceErrorHeightFalloff",
   "skipLevelOfDetail",
   "baseScreenSpaceError",
   "skipScreenSpaceErrorFactor",
   "skipLevels",
   "immediatelyLoadDesiredLevelOfDetail",
   "loadSiblings",
   "clippingPlanes",
   "classificationType",
   "ellipsoid",
   "lightColor",
   "colorBlendAmount",
   "colorBlendMode",
   "debugFreezeFrame",
   "debugColorizeTiles",
   "debugWireframe",
