   "debugShowContentBoundingVolume",
   "debugShowViewerRequestVolume",
   "debugShowGeometricError",
   "debugShowRenderingStatistics",
   "debugShowMemoryUsage",
   "debugShowUrl",
   "style",
   "backFaceCulling",
   "vectorClassificationOnly",
   "vectorKeepDecodedPositions",
   "splitDirection",
