+type ReadyTarget<T> = T & {
+  ready?: boolean;
+  readyEvent?: {
+    addEventListener(callback: (target: T) => void): void;
+  };
+};
+
+type ReadyScene = {
+  postRender?: {
+    addEventListener(callback: () => void): (() => void) | void;
+  };
+};
+
+export function callOnReady<T>(target: ReadyTarget<T>, callback: (target: T) => void, scene?: ReadyScene) {
+  if (target.ready) {
+    callback(target);
+    return;
+  }
+
+  if (target.readyEvent) {
+    target.readyEvent.addEventListener(() => callback(target));
+    return;
+  }
+
+  const removeListener = scene?.postRender?.addEventListener(() => {
+    if (!target.ready) return;
+    callback(target);
+    removeListener?.();
+  });
+}
+

